        // Per-canvas dirty state — shared _lastDiskR/_lastDiskW caused all 3 charts to skip rendering
        // because DrawStorageActivityChart updated the shared value first, then DrawSharedDiskChart found "no change"
        private readonly System.Collections.Generic.Dictionary<string, (float r, float w)> _diskChartLastVals = new();
        private readonly System.Collections.Generic.Dictionary<string, int> _diskChartSkipCount = new();
        private readonly System.Collections.Generic.HashSet<string> _diskChartForceRedraw = new();
        private const int DiskChartForceRedrawEvery = 4;

        private void DrawBenchDiskActivityChart(bool forceRedraw = false) => DrawSharedDiskChart("BenchDiskActivityCanvas", "TxtBenchDiskRead", "TxtBenchDiskWrite", "TxtBenchDiskLatency", forceRedraw);
        private void DrawSurfaceDiskActivityChart(bool forceRedraw = false) => DrawSharedDiskChart("SurfaceDiskActivityCanvas", "TxtSurfaceDiskRead", "TxtSurfaceDiskWrite", "TxtSurfaceDiskLatency", forceRedraw);
        private void DrawSmartDiskActivityChart(bool forceRedraw = false)   => DrawSharedDiskChart("SmartDiskActivityCanvas", "TxtSmartDiskRead", "TxtSmartDiskWrite", "TxtSmartDiskLatency", forceRedraw);

        private static string DiskTabIndex(string canvasName) => canvasName switch
        {
            "StorageActivityCanvas" => "1",
            "SmartDiskActivityCanvas" => "2",
            "SurfaceDiskActivityCanvas" => "3",
            "BenchDiskActivityCanvas" => "4",
            _ => "1",
        };

        private void DrawSharedDiskChart(string canvasName, string readLabelName, string writeLabelName, string? latencyLabelName = null, bool forceRedraw = false)
        {
            var canvas = FindName(canvasName) as System.Windows.Controls.Canvas;
            if (canvas == null)
            {
                return;
            }
            double w = canvas.ActualWidth, h = canvas.ActualHeight;
            if (!double.IsFinite(w) || !double.IsFinite(h) || w < 4 || h < 4)
            {
                return;
            }

            string idx = DiskTabIndex(canvasName);
            bool showLatency = SettingsService.Current.ShowDiskLatency;
            if (FindName($"ChkDiskLatency{idx}") is System.Windows.Controls.CheckBox latCb && latCb.IsChecked != showLatency)
                latCb.IsChecked = showLatency;

            float curR = _storageActR.Count > 0 ? _storageActR[0] : 0f;
            float curW = _storageActW.Count > 0 ? _storageActW[0] : 0f;

            if (FindName(readLabelName)  is System.Windows.Controls.TextBlock tr)
                tr.Text = FormatKBps(curR);
            if (FindName(writeLabelName) is System.Windows.Controls.TextBlock tw)
                tw.Text = FormatKBps(curW);
            if (!string.IsNullOrEmpty(latencyLabelName) && FindName(latencyLabelName) is System.Windows.Controls.TextBlock tl)
            {
                tl.Visibility = showLatency ? Visibility.Visible : Visibility.Collapsed;
                if (showLatency) tl.Text = _lastDiskAvgMs < 1 ? "<1 ms" : $"{_lastDiskAvgMs:F1} ms";
            }
            if (FindName($"DiskLatencyAxis{idx}") is FrameworkElement latAxis)
                latAxis.Visibility = showLatency ? Visibility.Visible : Visibility.Collapsed;
            if (_diskLatencyOverlayPaths.TryGetValue(canvas, out var latPath))
                latPath.Visibility = showLatency ? Visibility.Visible : Visibility.Collapsed;

            if (FindName($"TxtDiskSpeedMax{idx}") is System.Windows.Controls.TextBlock speedMaxTb)
            {
                var fullRForMax = _storageActR.ToArray();
                var fullWForMax = _storageActW.ToArray();
                int winForMax = Math.Min(_storageWindowSec, fullRForMax.Length);
                float visibleMax = Math.Max(1f, Math.Max(curR, curW));
                foreach (var v in fullRForMax[^winForMax..]) if (!float.IsNaN(v) && v > visibleMax) visibleMax = v;
                foreach (var v in fullWForMax[^Math.Min(_storageWindowSec, fullWForMax.Length)..]) if (!float.IsNaN(v) && v > visibleMax) visibleMax = v;
                float niceMax = visibleMax switch
                {
                    <= 256f    => (float)Math.Ceiling(visibleMax / 32f) * 32f,
                    <= 2048f   => (float)Math.Ceiling(visibleMax / 256f) * 256f,
                    <= 20480f  => (float)Math.Ceiling(visibleMax / 2048f) * 2048f,
                    _          => (float)Math.Ceiling(visibleMax / 20480f) * 20480f,
                };
                speedMaxTb.Text = FormatKBps(niceMax);
            }

            bool forced = forceRedraw || _diskChartForceRedraw.Remove(canvasName);
            _diskChartLastVals.TryGetValue(canvasName, out var last);
            bool unchanged = !forced && Math.Abs(curR - last.r) < 1f && Math.Abs(curW - last.w) < 1f;
            _diskChartSkipCount.TryGetValue(canvasName, out int skips);
            if (unchanged && skips < DiskChartForceRedrawEvery)
            {
                _diskChartSkipCount[canvasName] = skips + 1;
                return;
            }
            _diskChartSkipCount[canvasName] = 0;
            _diskChartLastVals[canvasName] = (curR, curW);

            var fullR = _storageActR.ToArray();
            var fullW = _storageActW.ToArray();
            int windowPts = Math.Min(_storageWindowSec, fullR.Length);
            var actRArr = fullR[^windowPts..];
            var actWArr = fullW[^windowPts..];

            DrawChart(canvas, actRArr, _penDiskRead, SettingsService.Current.ChartShowFill, 0f, -1f, actWArr, _penDiskWrite);

            if (showLatency)
            {
                var fullLat = _storageActLatency.ToArray();
                var latArr = fullLat[^Math.Min(_storageWindowSec, fullLat.Length)..];
                DrawDiskLatencyOverlay(canvas, latArr, $"TxtDiskLatMax{idx}");
            }
        }

        private void DrawDiskLatencyOverlay(System.Windows.Controls.Canvas canvas, float[] latMs, string? maxLabelName = null)
        {
            if (latMs.Length < 2) return;
            double w = canvas.ActualWidth, h = canvas.ActualHeight;
            if (!double.IsFinite(w) || !double.IsFinite(h) || w < 6 || h < 6) return;

            float maxLat = 1f;
            foreach (var v in latMs) if (!float.IsNaN(v) && v > maxLat) maxLat = v;
            maxLat *= 1.25f; // margin, so the peak does not touch the top edge

            float niceMax = maxLat switch
            {
                <= 10f  => (float)Math.Ceiling(maxLat),
                <= 50f  => (float)Math.Ceiling(maxLat / 5.0) * 5f,
                <= 200f => (float)Math.Ceiling(maxLat / 10.0) * 10f,
                _       => (float)Math.Ceiling(maxLat / 50.0) * 50f,
            };
            if (!string.IsNullOrEmpty(maxLabelName) && FindName(maxLabelName) is System.Windows.Controls.TextBlock maxTb)
                maxTb.Text = niceMax < 1f ? "<1 ms" : $"{niceMax:F0} ms";

            var pts = new List<System.Windows.Point>(latMs.Length);
            for (int i = 0; i < latMs.Length; i++)
            {
                float v = latMs[i];
                if (float.IsNaN(v)) continue;
                double x = w * i / (latMs.Length - 1);
                double y = h - Math.Clamp(v / maxLat, 0f, 1f) * h;
                pts.Add(new System.Windows.Point(x, y));
            }
            if (pts.Count < 2) return;

            var geo = new System.Windows.Media.StreamGeometry();
            using (var ctx = geo.Open())
            {
                ctx.BeginFigure(pts[0], false, false);
                ctx.PolyLineTo(pts.Skip(1).ToList(), true, false);
            }
            geo.Freeze();

            if (!_diskLatencyOverlayPaths.TryGetValue(canvas, out var path) || !canvas.Children.Contains(path))
            {
                var brush = TryFindResource("TextSecondaryBrush") as System.Windows.Media.Brush ?? System.Windows.Media.Brushes.Gray;
                var pen = new System.Windows.Media.Pen(brush, 1.25)
                {
                    DashStyle = new System.Windows.Media.DashStyle(new double[] { 2, 2 }, 0),
                };
                pen.Freeze();
                path = new System.Windows.Shapes.Path
                {
                    Stroke = pen.Brush,
                    StrokeThickness = pen.Thickness,
                    StrokeDashArray = pen.DashStyle.Dashes,
                    Opacity = 0.55,
                    IsHitTestVisible = false, // must not steal clicks/hover from the canvas
                };
                _diskLatencyOverlayPaths[canvas] = path;
                canvas.Children.Add(path);
            }
            path.Visibility = Visibility.Visible;
            path.Data = geo;
        }

        private readonly Dictionary<System.Windows.Controls.Canvas, System.Windows.Shapes.Path> _diskLatencyOverlayPaths = new();

        internal void ToggleDiskLatency_Click(object sender, RoutedEventArgs e)
        {
            bool show = (sender as System.Windows.Controls.CheckBox)?.IsChecked == true;
            SettingsService.Current.ShowDiskLatency = show;
            SettingsService.Save();
            foreach (var name in new[] { "ChkDiskLatency1", "ChkDiskLatency2", "ChkDiskLatency3", "ChkDiskLatency4" })
                if (FindName(name) is System.Windows.Controls.CheckBox cb) cb.IsChecked = show;
            DrawStorageActivityChart();
            DrawBenchDiskActivityChart();
            DrawSurfaceDiskActivityChart();
            DrawSmartDiskActivityChart();
        }

        private void ApplyDiskWindowButtonSelectedState(Border btn, bool active)
        {
            var res = System.Windows.Application.Current.Resources;
            if (active)
            {
                btn.Background = res["SelBtnBg"] as System.Windows.Media.Brush ?? System.Windows.Media.Brushes.Transparent;
                btn.BorderBrush = res["SelBtnBorderBrush"] as System.Windows.Media.Brush ?? System.Windows.Media.Brushes.Transparent;
                btn.BorderThickness = res["SelBtnBorderThickness"] as Thickness? ?? new Thickness(1);
                btn.Effect = null;   // no shadow on a button with text: it blurs the text
                if (btn.Child is System.Windows.Controls.TextBlock tb)
                    tb.Foreground = res["SelBtnFg"] as System.Windows.Media.Brush ?? System.Windows.Media.Brushes.White;
            }
            else
            {
                btn.SetResourceReference(Border.BackgroundProperty, "BgCardBrush");
                btn.ClearValue(Border.BorderBrushProperty);
                btn.ClearValue(Border.BorderThicknessProperty);
                btn.ClearValue(Border.EffectProperty);
                if (btn.Child is System.Windows.Controls.TextBlock tb)
                    tb.SetResourceReference(TextBlock.ForegroundProperty, "TextSecondaryBrush");
            }
        }

        // Re-applies the current style (SelBtn*) to all 16 Disk Activity time-window buttons, without changing which one is
        // selected — called from ApplySelectedButtonStyleExperiment() when another style is chosen in the Dev Panel.
        private void RefreshDiskWindowButtonsStyle()
        {
            foreach (var (name, wSec) in new[]{
                ("StorageWin60",60),("StorageWin5m",300),("StorageWin10m",900),("StorageWin1h",3600),
                ("BenchDiskWin60",60),("BenchDiskWin5m",300),("BenchDiskWin10m",900),("BenchDiskWin1h",3600),
                ("SurfaceDiskWin60",60),("SurfaceDiskWin5m",300),("SurfaceDiskWin10m",900),("SurfaceDiskWin1h",3600),
                ("SmartDiskWin60",60),("SmartDiskWin5m",300),("SmartDiskWin10m",900),("SmartDiskWin1h",3600)})
            {
                if (FindName(name) is Border btn)
                    ApplyDiskWindowButtonSelectedState(btn, wSec == _storageWindowSec);
            }
        }

        private void SetStorageWindow(int sec)
        {
            _storageWindowSec = sec;
            AppLogger.Info($"S-DIAG SetStorageWindow: sec={sec}, _storageWindowSec now={_storageWindowSec}");
            foreach (var (name, wSec) in new[]{
                ("StorageWin60",60),("StorageWin5m",300),("StorageWin10m",900),("StorageWin1h",3600),
                ("BenchDiskWin60",60),("BenchDiskWin5m",300),("BenchDiskWin10m",900),("BenchDiskWin1h",3600),
                ("SurfaceDiskWin60",60),("SurfaceDiskWin5m",300),("SurfaceDiskWin10m",900),("SurfaceDiskWin1h",3600),
                ("SmartDiskWin60",60),("SmartDiskWin5m",300),("SmartDiskWin10m",900),("SmartDiskWin1h",3600)})
            {
                if (FindName(name) is Border btn)
                    ApplyDiskWindowButtonSelectedState(btn, wSec == sec);
            }
            DrawStorageActivityChart(forceRedraw: true);
            DrawBenchDiskActivityChart(forceRedraw: true);
            DrawSurfaceDiskActivityChart(forceRedraw: true);
            DrawSmartDiskActivityChart(forceRedraw: true);
        }
